def transform(grid):
    """Combine four same-sized color masks using priority 5 > 4 > 8 > 2."""
    h, w = len(grid), len(grid[0])
    if h % 4:
        raise ValueError("expected four equal-height layers")
    block = h // 4
    out = [[0] * w for _ in range(block)]
    for r in range(block):
        for c in range(w):
            values = [grid[layer * block + r][c] for layer in range(4)]
            for color in (5, 4, 8, 2):
                if color in values:
                    out[r][c] = color
                    break
    return out
